sys_script.script:
/**
 * ESR - Validate category and subcategory
 *
 * Authoritative server-side guard on the Category/Subcategory relationship.
 * Runs for every insert and update regardless of origin: the platform form,
 * the Raise a Ticket view, list inline edit, the REST Table API, the employee
 * homepage, or any script. Client-side filtering is a convenience only; this
 * is the rule that actually protects data integrity.
 *
 * Subcategory is optional, so an empty subcategory always passes.
 */
;(function executeRule(current, previous /*null when async*/) {
    var category = current.getValue('category')
    var subcategory = current.getValue('subcategory')

    // Nothing to check when no subcategory has been chosen.
    if (!subcategory) {
        return
    }

    var utils = new x_412993_employe_1.EsrSubcategoryUtils()
    var result = utils.validatePair(category, subcategory)

    if (result.valid) {
        return
    }

    gs.addErrorMessage(result.message)
    current.setAbortAction(true)
})(current, previous)
